import React, { useEffect, useRef, useState } from "react";
import { Html5QrcodeScanner } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const lastScanRef = useRef(null);

  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  const playSound = () => {
    const audio = new Audio("/success.mp3");
    audio.play();
  };

  useEffect(() => {
    const scanner = new Html5QrcodeScanner(
      "reader",
      {
        fps: 40,
        qrbox: { width: 200, height: 200 },
      },
      false,
    );

    scannerRef.current = scanner;

    scanner.render(async (decodedText) => {
      if (lastScanRef.current === decodedText) return;
      lastScanRef.current = decodedText;

      try {
        const userId = decodedText;

        const verifyRes = await fetch(
          `http://localhost:5000/verify-user/${userId}`,
        );

        const verifyData = await verifyRes.json();

        if (!verifyData.success) {
          setStatus("notfound");
          setStudent(null);
          return;
        }

        setStudent(verifyData.user);

        const attendanceRes = await fetch(
          `http://localhost:5000/mark-attendance/${userId}`,
          { method: "PUT" },
        );

        const attendanceData = await attendanceRes.json();

        if (attendanceData.success) {
          setStatus("success");
          playSound();
        } else {
          setStatus("already");
        }
      } catch (error) {
        setStatus("servererror");
      }

      setTimeout(() => {
        lastScanRef.current = null;
      }, 2000);
    });

    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear();
      }
    };
  }, []);

  return (
    <div style={{ textAlign: "center" }}>
      <h2>QR Attendance Scanner</h2>

      <div id="reader" style={{ width: "350px", margin: "auto" }}></div>

      {student && (
        <div
          style={{
            width: "320px",
            margin: "20px auto",
            padding: "20px",
            borderRadius: "10px",
            background: "#f5f5f5",
          }}
        >
          <img
            src={`http://localhost:5000/${student.photo}`}
            alt="student"
            width="100"
          />

          <h3>{student.name}</h3>

          <p>{student.college_name}</p>

          {status === "success" && (
            <h2 style={{ color: "green" }}>✔ Attendance Marked</h2>
          )}

          {status === "already" && (
            <h2 style={{ color: "red" }}>❌ Already Scanned</h2>
          )}
        </div>
      )}
    </div>
  );
}

export default QRScanner;
